faq.push(
 F('prepare-before-entry','migration',
  T('Что проверить до покупки билета и выезда?','Билет алып, жолға шықпас бұрын нені тексеремін?','What should I check before buying a ticket and travelling?'),
  T('Начните с действительных документов, порядка въезда для своего гражданства и цели поездки. Согласуйте принимающую сторону и способ получить подтверждения. Это план подготовки: он не подтверждает допуск через границу.','Алдымен құжаттардың жарамдылығын, азаматтық пен сапар мақсатына сай кіру тәртібін тексеріңіз. Қабылдаушы тарапты және растаулар алу тәсілін келісіңіз. Бұл дайындық жоспары, шекарадан өткізу кепілдігі емес.','Start by checking valid documents and entry requirements for your citizenship and purpose. Agree who will host you and how to obtain confirmations. This preparation plan does not guarantee admission at the border.'),
  [T('Проверьте требования у официального консульства и перевозчика.','Талаптарды ресми консулдықтан және тасымалдаушыдан тексеріңіз.','Check requirements with the official consulate and carrier.'),T('Уточните документы и правила для конкретного пункта въезда.','Нақты кіру пунктіне қажет құжаттар мен тәртіпті нақтылаңыз.','Confirm documents and procedures for the particular entry point.'),T('Согласуйте с принимающей стороной действия после прибытия.','Қабылдаушы тараппен келгеннен кейінгі әрекеттерді келісіңіз.','Agree post-arrival actions with the host.')],
  T('Консульство РК; принимающая сторона; перевозчик','ҚР консулдығы; қабылдаушы тарап; тасымалдаушы','Kazakhstan consulate; the host; the carrier'),
  T('Какие требования действуют для моего гражданства, цели, даты и пункта въезда?','Азаматтығыма, мақсатыма, күнім мен кіру пунктіме қандай талаптар қолданылады?','Which requirements apply to my citizenship, purpose, date and entry point?'),['entry','faq-qazeta']),
 F('qazeta-entry','migration',
  T('Нужно ли мне оформлять QazETA перед поездкой?','Сапар алдында QazETA ресімдеуім керек пе?','Do I need QazETA before travelling?'),
  T('Официальное разъяснение описывает поэтапное внедрение и переходный период. Проверяйте условия по дате, пункту въезда и своим основаниям. Электронное разрешение не заменяет остальные требования к въезду и пребыванию.','Ресми түсіндірме кезең-кезеңімен енгізу мен өтпелі кезеңді сипаттайды. Күнге, кіру пунктіне және негізіңізге сай талаптарды тексеріңіз. Электрондық рұқсат өзге кіру және болу талаптарын алмастырмайды.','Official guidance describes phases and a transition period. Check requirements for your date, entry point and grounds. Electronic authorisation does not replace other entry and stay requirements.'),
  [T('Откройте официальное разъяснение и раздел об этапах.','Ресми түсіндірме мен кезеңдер бөлімін ашыңыз.','Read the official guidance and phase schedule.'),T('Уточните применимость и исключения у консульства.','Қолданылуы мен ерекшеліктерін консулдықтан нақтылаңыз.','Confirm applicability and exceptions with the consulate.'),T('Используйте официальный канал, не посредников из чата.','Чаттағы делдалды емес, ресми арнаны пайдаланыңыз.','Use an official channel rather than chat intermediaries.')],
  T('Консульство РК; официальный канал QazETA','ҚР консулдығы; QazETA ресми арнасы','Kazakhstan consulate; the official QazETA channel'),
  T('На какую дату и пункт въезда распространяется порядок в моей ситуации?','Менің жағдайымда тәртіп қай күн мен кіру пунктіне қолданылады?','Which date and entry point rules apply to my situation?'),['faq-qazeta','entry']),
 F('extend-stay-plan','migration',
  T('Хочу остаться дольше первоначального плана. Что подготовить для уточнения?','Бастапқы жоспардан ұзағырақ қалғым келеді. Нені дайындаймын?','I want to stay longer than planned. What should I prepare for an enquiry?'),
  T('Не считайте изменение личного плана продлением разрешённого пребывания. До окончания применимого срока уточните основание, процедуру и документы. Migrato не определяет возможность продления по одной категории посетителя.','Жеке жоспарды өзгерту рұқсат етілген мерзімді ұзарту емес. Қолданылатын мерзім аяқталғанға дейін негізді, рәсімді және құжаттарды нақтылаңыз. Migrato тек санатқа қарап ұзарту мүмкіндігін анықтамайды.','Changing your plan does not extend authorised stay. Before the applicable period ends, confirm the grounds, procedure and documents. Migrato cannot determine extension eligibility from your category alone.'),
  [T('Подготовьте даты поездок и имеющиеся документы для официального обращения.','Ресми жүгіну үшін сапар күндері мен құжаттарды дайындаңыз.','Prepare travel dates and existing documents for an official enquiry.'),T('Уточните новое основание и необходимые действия до окончания срока.','Жаңа негіз бен мерзім біткенге дейінгі әрекеттерді нақтылаңыз.','Confirm the new grounds and actions needed before expiry.'),T('Попросите перечень документов и способ подтверждения результата.','Құжаттар тізімі мен нәтиже растауын сұраңыз.','Request the document list and how the outcome is confirmed.')],
  T('Миграционная служба; принимающая сторона','Көші-қон қызметі; қабылдаушы тарап','Migration services; your host'),
  T('Какие законные варианты и действия доступны до окончания моего текущего основания?','Қазіргі негізім аяқталғанға дейін қандай заңды нұсқалар мен әрекеттер бар?','Which lawful options and steps are available before my current grounds expire?'),['faq-rvp-guide','migration','entry']),
 F('change-stay-purpose','migration',
  T('Цель приезда изменилась: учёба закончилась или появилась работа. Что делать?','Келу мақсаты өзгерді: оқу аяқталды не жұмыс табылды. Не істеймін?','My purpose changed: study ended or I found work. What should I do?'),
  T('Официальное разъяснение предлагает проверить необходимость оформления разрешения по новому основанию. РВП по одной цели не заменяет отдельную проверку требований к работе. Не ограничивайтесь сменой категории на сайте.','Ресми түсіндірме жаңа негіз бойынша рұқсат ресімдеу қажеттілігін тексеруді ұсынады. Бір мақсатқа берілген уақытша тұру рұқсаты жұмыс талаптарын бөлек тексеруді алмастырмайды. Сайттағы санатты өзгерту жеткіліксіз.','Official guidance advises checking whether permission under new grounds is needed. Residence permission for one purpose does not replace a separate work-eligibility check. Changing a website category is not sufficient.'),
  [T('Уточните дату и обстоятельство изменения.','Өзгерген күн мен мән-жайды нақтылаңыз.','Identify when and how the circumstances changed.'),T('Свяжитесь с вузом или работодателем и миграционной службой.','ЖОО не жұмыс берушімен және көші-қон қызметімен байланысыңыз.','Contact the institution or employer and migration services.'),T('Получите порядок перехода и перечень подтверждений.','Ауысу тәртібі мен растаулар тізімін алыңыз.','Obtain the transition process and required evidence.')],
  T('Миграционная служба; вуз или работодатель','Көші-қон қызметі; ЖОО немесе жұмыс беруші','Migration services; the institution or employer'),
  T('Нужно ли новое основание и какие действия выполнить при изменении цели?','Жаңа негіз керек пе және мақсат өзгергенде қандай әрекеттер қажет?','Are new grounds needed, and what steps follow a change of purpose?'),['faq-rvp-guide','migration','labour']),
 F('passport-validity-check','documents',
  T('Как проверить, подойдёт ли мой документ для въезда и процедур?','Құжатымның кіру мен рәсімдерге жарайтынын қалай тексеремін?','How can I check whether my document is accepted for entry and procedures?'),
  T('Проверьте вид документа, срок его действия и совпадение данных. Требования могут различаться по гражданству, соглашению и процедуре; универсальный запас месяцев здесь не назначается. При замене документа отдельно уточните обновление связанных сведений.','Құжат түрін, жарамдылық мерзімін және деректер сәйкестігін тексеріңіз. Талап азаматтыққа, келісімге және рәсімге байланысты; мұнда бәріне ортақ ай саны белгіленбейді. Құжат ауысса, байланысты деректерді жаңартуды нақтылаңыз.','Check the document type, validity and consistent details. Requirements may depend on citizenship, agreements and the procedure; no universal number of remaining months is assigned here. If it changes, ask about updating linked records.'),
  [T('Сверьте сведения в документе и подтверждениях.','Құжат пен растаулардағы деректерді салыстырыңыз.','Compare the document details with your confirmations.'),T('Уточните требования у консульства и получателя услуги.','Талаптарды консулдықтан және қызмет көрсетушіден нақтылаңыз.','Confirm requirements with the consulate and service provider.'),T('Не загружайте документ в учебный сайт.','Құжатты оқу сайтына жүктемеңіз.','Do not upload the document to this learning site.')],
  T('Консульство; миграционная служба; получатель документов','Консулдық; көші-қон қызметі; құжат қабылдаушы','The consulate; migration services; the document recipient'),
  T('Принимается ли этот вид документа и какие сведения обновить при его замене?','Бұл құжат түрі қабылдана ма және ауысса қай деректерді жаңартамын?','Is this document type accepted, and which records need updating if it changes?'),['entry','iin','faq-consular']),
 F('document-translation','documents',
  T('Нужен ли нотариальный перевод для ИИН и других обращений?','ЖСН және басқа жүгінулер үшін нотариалды аударма керек пе?','Do I need a notarised translation for an IIN or other applications?'),
  T('Карточка ИИН связывает перевод с отсутствием указанных установочных данных на кириллице или латинице. Это условие конкретной услуги, не универсальное правило всех обращений. Для другой процедуры запросите её собственный перечень.','ЖСН қызмет карточкасында қажетті деректер кириллица не латын әрпімен болмаса, аударма көзделген. Бұл нақты қызмет талабы, барлық жүгінуге ортақ ереже емес. Өзге рәсім үшін оның жеке тізімін сұраңыз.','The IIN service page links translation to specified identity details not appearing in Cyrillic or Latin characters. This is a service-specific condition, not a universal rule. Request the separate list for other procedures.'),
  [T('Прочитайте перечень именно выбранной услуги.','Таңдалған қызметтің нақты тізімін оқыңыз.','Read the list for the particular service.'),T('Уточните язык, объём и вид удостоверения перевода.','Аударма тілін, көлемін және куәландыру түрін нақтылаңыз.','Confirm the language, scope and certification required.'),T('Согласуйте написание имени по исходному документу.','Аты-жөннің жазылуын бастапқы құжатпен салыстырыңыз.','Check name spelling against the original document.')],
  T('ЦОН; услугодатель; нотариус по вопросу удостоверения','ХҚКО; қызмет көрсетуші; куәландыру бойынша нотариус','Public service centre; the provider; a notary for certification questions'),
  T('Требуется ли перевод по условиям этой услуги и в каком виде?','Осы қызмет шарттары бойынша аударма қажет пе және қандай түрде?','Is translation required for this service, and in what form?'),['iin']),
 F('document-copies-safety','documents',
  T('Кому передавать копии документов и как сохранять подтверждения?','Құжат көшірмесін кімге беріп, растауларды қалай сақтаймын?','Who should receive document copies, and how should I keep confirmations?'),
  T('Это рекомендация команды по безопасной подготовке: уточняйте получателя, назначение и официальный канал передачи. Сохраняйте свои подтверждения в защищённом месте. Migrato не принимает документы и не проверяет личные реквизиты.','Бұл — қауіпсіз дайындық туралы команда кеңесі: алушыны, мақсатты және ресми беру арнасын нақтылаңыз. Растауларды қауіпсіз жерде сақтаңыз. Migrato құжаттарды қабылдамайды және жеке деректерді тексермейді.','This is team guidance for safe preparation: confirm the recipient, purpose and official submission channel. Keep your own confirmations securely. Migrato does not accept documents or verify personal details.'),
  [T('Проверьте официальный контакт организации самостоятельно.','Ұйымның ресми байланысын өзіңіз тексеріңіз.','Independently verify the organisation’s official contact.'),T('Спросите, какой документ действительно необходим.','Шынымен қандай құжат қажет екенін сұраңыз.','Ask which document is actually required.'),T('Не отправляйте пароли и банковские коды вместе с копиями.','Көшірмелермен бірге құпиясөз бен банк кодын жібермеңіз.','Do not send passwords or bank codes with copies.')],
  T('Официальный получатель документов; банк по вопросам безопасности','Құжаттың ресми алушысы; қауіпсіздік бойынша банк','The official document recipient; the bank for security questions'),
  T('Зачем требуется копия и каким официальным способом её предоставить?','Көшірме не үшін қажет және оны қай ресми тәсілмен беремін?','Why is a copy needed, and which official submission method should I use?'),['privacy','faq-bank-safety']),
 F('unpaid-wages','work',
  T('Работодатель не выплачивает деньги или условия отличаются от договора. Куда обратиться?','Жұмыс беруші төлемесе не шарт талаптарын өзгертсе, қайда жүгінемін?','My employer has not paid or the terms differ from the contract. Where should I turn?'),
  T('Сначала соберите договор, подтверждения работы и расчётов и письменно уточните предмет разногласия. Компетентный порядок зависит от отношений и обстоятельств; учебный сайт не устанавливает задолженность или итог спора.','Алдымен шартты, жұмыс пен есеп айырысу растауларын жинап, келіспеушілікті жазбаша нақтылаңыз. Тәртіп қатынас пен мән-жайға байланысты; оқу сайты қарызды не даудың нәтижесін анықтамайды.','Gather the agreement and records of work and payments, then clarify the disagreement in writing. The proper process depends on the relationship and circumstances; this learning site does not establish a debt or decide the dispute.'),
  [T('Сохраните договор, расчётные документы и переписку у себя.','Шартты, есеп құжаттарын және хат алмасуды өзіңізде сақтаңыз.','Keep your agreement, payment records and correspondence.'),T('Запросите письменное объяснение у работодателя.','Жұмыс берушіден жазбаша түсіндірме сұраңыз.','Ask the employer for a written explanation.'),T('Уточните компетенцию инспекции труда или специалиста и срок обращения.','Еңбек инспекциясы не маман құзыреті мен жүгіну мерзімін нақтылаңыз.','Confirm the labour inspectorate’s or specialist’s remit and applicable time limits.')],
  T('Работодатель; территориальная инспекция труда; квалифицированный специалист','Жұмыс беруші; аумақтық еңбек инспекциясы; білікті маман','The employer; territorial labour inspectorate; a qualified adviser'),
  T('Какой порядок защиты применим к моим отношениям и какие доказательства подготовить?','Қатынасыма қандай қорғау тәртібі қолданылады және қандай дәлел керек?','Which process applies to this relationship, and what evidence should I prepare?'),['labour','faq-public-appeals']),
 F('study-status-change','study',
  T('Я перевёлся, взял перерыв или прекратил обучение. Что проверить?','Басқа оқу орнына ауыстым, үзіліс алдым не оқуды тоқтаттым. Нені тексеремін?','I transferred, paused or ended my studies. What should I check?'),
  T('Уточните в вузе дату и содержание изменения, а затем влияние на документы принимающей стороны и основание пребывания. Учебный статус в Migrato не обновляет разрешения и не подтверждает право продолжать пребывание.','ЖОО-дан өзгерістің күні мен мазмұнын, кейін қабылдаушы тарап құжаттары мен болу негізіне әсерін нақтылаңыз. Migrato-дағы оқу мәртебесі рұқсатты жаңартпайды және қалу құқығын растамайды.','Confirm the change and its date with the institution, then its effect on receiving-party documents and grounds of stay. A Migrato study category does not update permits or confirm a right to remain.'),
  [T('Получите подтверждение изменения от учебного заведения.','Оқу орнынан өзгеріс растауын алыңыз.','Obtain confirmation of the change from the institution.'),T('Обсудите необходимые действия с ответственным подразделением вуза.','Қажетті әрекеттерді ЖОО-ның жауапты бөлімімен талқылаңыз.','Discuss the steps with the institution’s responsible office.'),T('Уточните новое основание и порядок в миграционной службе.','Көші-қон қызметінен жаңа негіз бен тәртіпті нақтылаңыз.','Confirm any new grounds and process with migration services.')],
  T('Международный или учебный отдел вуза; миграционная служба','ЖОО-ның халықаралық не оқу бөлімі; көші-қон қызметі','The institution’s international or academic office; migration services'),
  T('Какие сведения и документы нужно изменить после изменения моего обучения?','Оқуым өзгерген соң қандай дерек пен құжатты өзгерту керек?','Which records and documents need updating following this study change?'),['faq-rvp-guide','migration']),
 F('currency-status-check','finance',
  T('Виза, гражданство и валютное резидентство означают одно и то же?','Виза, азаматтық және валюталық резиденттік бірдей ме?','Are visa status, citizenship and currency residence the same thing?'),
  T('Не переносите вывод из одной процедуры в другую. Для конкретной операции попросите банк назвать применимые критерии и подтверждения. Этот FAQ не определяет ваш валютный или налоговый статус и не рассчитывает обязанности по числу дней.','Бір рәсімнің қорытындысын екіншісіне көшірмеңіз. Нақты операция үшін банктен өлшемдер мен растауларды атауды сұраңыз. Бұл FAQ валюталық не салық мәртебесін анықтамайды және күн санымен міндет есептемейді.','Do not carry a conclusion from one procedure into another. For a transaction, ask the bank to identify the applicable criteria and evidence. This FAQ does not determine currency or tax status or infer obligations from a day count.'),
  [T('Назовите банку вид планируемой операции без передачи данных в Migrato.','Migrato-ға дерек бермей, банкке операция түрін айтыңыз.','Tell the bank the transaction type without sending details to Migrato.'),T('Попросите точную норму и перечень подтверждений.','Нақты норма мен растаулар тізімін сұраңыз.','Request the exact provision and evidence list.'),T('Налоговый вопрос отдельно направьте в орган государственных доходов.','Салық мәселесін мемлекеттік кіріс органына бөлек жолдаңыз.','Refer tax questions separately to the state revenue authority.')],
  T('Выбранный банк; Национальный банк; орган государственных доходов','Таңдалған банк; Ұлттық банк; мемлекеттік кіріс органы','The selected bank; the National Bank; the state revenue authority'),
  T('По какой норме определяется статус для этой операции и чем его подтвердить?','Осы операция үшін мәртебе қай нормамен анықталады және немен расталады?','Which provision determines status for this transaction, and how is it evidenced?'),['currency','bank','faq-tax']),
 F('bank-fees-check','finance',
  T('Как заранее сравнить комиссии и условия счёта?','Шот комиссиялары мен шарттарын алдын ала қалай салыстырамын?','How can I compare account fees and terms in advance?'),
  T('Сравнивайте официальные тарифы для одного вида операции и условий клиента. Уточните обслуживание, переводы, конвертацию и закрытие счёта. Это рекомендация по подготовке: в FAQ не назначаются текущие цены или гарантированная доступность продукта.','Бір операция түрі мен клиент шарты үшін ресми тарифтерді салыстырыңыз. Қызмет көрсету, аудару, айырбастау және шот жабуды нақтылаңыз. Бұл дайындық кеңесі: FAQ ағымдағы баға не өнім қолжетімділігіне кепілдік бермейді.','Compare official tariffs for the same operation and customer conditions. Ask about maintenance, transfers, conversion and closure. This preparation guidance provides neither current prices nor a guarantee that a product is available.'),
  [T('Запросите действующий тариф и дату его применения.','Қолданыстағы тариф пен қолданылу күнін сұраңыз.','Request the current tariff and its effective date.'),T('Сравните полную стоимость предполагаемых операций.','Жоспарланған операциялардың толық құнын салыстырыңыз.','Compare the full cost of the planned transactions.'),T('Уточните возможные дополнительные документы и ограничения.','Қосымша құжаттар мен шектеулерді нақтылаңыз.','Confirm additional documents and restrictions.')],
  T('Официальная поддержка выбранного банка','Таңдалған банктің ресми қолдауы','The selected bank’s official support'),
  T('Какие комиссии и ограничения применимы к этому счёту и моей операции?','Осы шот пен операцияма қандай комиссия және шектеу қолданылады?','Which fees and restrictions apply to this account and transaction?'),['bank']),
 F('rental-handover','housing',
  T('Что зафиксировать при получении ключей и передаче квартиры?','Кілт пен пәтерді алғанда нені тіркеймін?','What should I record when receiving the keys and property?'),
  T('Команда рекомендует согласовать перечень имущества, состояние, показания счётчиков, ключи и подтверждения платежей. Запись должна соответствовать договорённости сторон; Migrato не удостоверяет состояние настоящего жилья.','Команда мүлік тізімін, жай-күйін, есептегіш көрсеткішін, кілт пен төлем растауын келісуді ұсынады. Жазба тараптар келісіміне сай болуы керек; Migrato нақты үйдің жағдайын куәландырмайды.','The team recommends agreeing the inventory, condition, meter readings, keys and payment evidence. The record should reflect the parties’ agreement; Migrato does not certify a real property’s condition.'),
  [T('Сопоставьте передаваемое с договором и перечнем имущества.','Берілгенді шартпен және мүлік тізімімен салыстырыңыз.','Compare what is handed over with the agreement and inventory.'),T('Обсудите обнаруженные недостатки до подтверждения передачи.','Қабылдауды растағанға дейін кемшіліктерді талқылаңыз.','Discuss defects before confirming handover.'),T('Сохраните согласованные подтверждения у себя, не на сайте.','Келісілген растауларды сайтта емес, өзіңізде сақтаңыз.','Keep agreed records yourself rather than on the site.')],
  T('Арендодатель или его уполномоченный представитель','Жалға беруші не уәкілетті өкілі','The landlord or authorised representative'),
  T('Как фиксируем состояние, имущество, ключи и неустранённые недостатки?','Жай-күйді, мүлікті, кілт пен түзетілмеген кемшіліктерді қалай тіркейміз?','How will we record condition, inventory, keys and unresolved defects?'),['civil']),
 F('rental-end-plan','housing',
  T('Как подготовиться к прекращению аренды и возврату депозита?','Жалдауды тоқтатып, кепілді қайтаруға қалай дайындаламын?','How can I prepare to end a rental and discuss deposit return?'),
  T('Сверьте договор и применимые нормы о прекращении, передаче жилья и расчётах. Единого срока возврата депозита для любой ситуации здесь не назначается. При споре готовьте подтверждения и обращайтесь за индивидуальной оценкой.','Шарт пен тоқтату, баспананы қайтару және есеп айырысу нормаларын салыстырыңыз. Мұнда барлық жағдайға ортақ кепіл қайтару мерзімі белгіленбейді. Дау болса, растаулар жинап, жеке бағалау сұраңыз.','Check the agreement and applicable termination, handover and payment rules. No universal deposit-return deadline is assigned here. If there is a dispute, gather records and seek an individual assessment.'),
  [T('Уточните основание, дату и способ уведомления другой стороны.','Негізді, күнді және екінші тарапқа хабарлау тәсілін нақтылаңыз.','Confirm the grounds, date and method of notifying the other party.'),T('Согласуйте передачу ключей, имущества и окончательные расчёты.','Кілт пен мүлікті қайтаруды және соңғы есепті келісіңіз.','Agree key and property handover and final payments.'),T('Попросите объяснить удержания и сохранить подтверждения.','Ұстап қалуды түсіндіруді сұрап, растауларды сақтаңыз.','Ask for any deductions to be explained and keep evidence.')],
  T('Арендодатель; квалифицированный специалист при споре','Жалға беруші; дау болса білікті маман','The landlord; a qualified adviser if disputed'),
  T('Каковы порядок прекращения, расчёт и документальное подтверждение возврата суммы?','Тоқтату тәртібі, есеп және соманы қайтару растауы қандай?','What are the termination process, final calculation and evidence of any refund?'),['civil'])
);

const entryTopics=new Set(['arrival-notification','change-address','prepare-before-entry','qazeta-entry']);
for(const item of faq){
 item.coverageTopic=item.category==='migration'?(entryTopics.has(item.id)?'entry':'stay'):item.category;
}
for(const source of faqSources){
 if(!('verifiedFull' in source)){
  source.verifiedFull=false;
  source.verificationScope=T('Источник указан как официальный ориентир; полная актуальная правовая применимость отдельно не подтверждена.','Дереккөз ресми бағдар ретінде берілген; толық өзекті құқықтық қолданылуы бөлек расталмады.','An official reference is provided; full current legal applicability was not independently confirmed.');
 }
}
for(const id of ['faq-emergency','faq-school','faq-public-appeals']){
 const source=faqSources.find(item=>item.id===id);
 source.checked='2026-11-13';source.verifiedFull=true;
 source.verificationScope=T('Прочитана официальная страница по указанной теме. Это не индивидуальное решение и не проверка полного законодательства.','Аталған тақырыптағы ресми парақша оқылды. Бұл жеке шешім не барлық заңнаманы тексеру емес.','The official guidance page for this topic was read. This is not an individual decision or a review of all legislation.');
}
for(const id of ['faq-bank-regulator','faq-tax']){
 const source=faqSources.find(item=>item.id===id);source.lastAttempted='2026-11-13';
}

for(const id of ['arrival-notification','three-procedures','change-address']){
 const item=faq.find(entry=>entry.id===id);
 item.sourceIds=['faq-rvp-guide',...item.sourceIds.filter(sourceId=>sourceId!=='faq-rvp-guide')];
 item.url=urls['faq-rvp-guide'];
}
